import json
import sys
import time
import uuid
from concurrent.futures import ThreadPoolExecutor, as_completed

import requests

BASE_URL = "http://localhost:8000"
EVENT_ID = "bfb57ea2-0217-4371-adf8-7a005be43143"
SEAT_ID = "1b7b7602-9fcd-4570-b7ab-b4d2e362160c"


def post(path, payload, timeout=10):
    return requests.post(f"{BASE_URL}{path}", json=payload, timeout=timeout)


def delete(path, timeout=10):
    return requests.delete(f"{BASE_URL}{path}", timeout=timeout)


def get(path, timeout=10):
    return requests.get(f"{BASE_URL}{path}", timeout=timeout)


def create_hold(user_id, ttl_seconds=30):
    payload = {
        "user_id": user_id,
        "event_id": EVENT_ID,
        "seat_id": SEAT_ID,
        "ttl_seconds": ttl_seconds,
    }
    response = post("/holds", payload)
    try:
        body = response.json()
    except Exception:
        body = response.text
    return {
        "status_code": response.status_code,
        "body": body,
        "user_id": user_id,
    }


def create_booking(user_id, hold_token, idempotency_key=None):
    payload = {
        "user_id": user_id,
        "event_id": EVENT_ID,
        "seat_id": SEAT_ID,
        "hold_token": hold_token,
        "payment_method": "credit_card",
        "card_details": {
            "card_number": "4242424242424242",
            "card_holder_name": "John Doe",
            "expiry_month": 12,
            "expiry_year": 2026,
            "cvv": "123",
        },
        "idempotency_key": idempotency_key or str(uuid.uuid4()),
    }
    response = post("/bookings", payload, timeout=30)
    try:
        body = response.json()
    except Exception:
        body = response.text
    return {
        "status_code": response.status_code,
        "body": body,
        "user_id": user_id,
    }


def release_hold(hold_token):
    response = delete(f"/holds/{hold_token}")
    try:
        body = response.json()
    except Exception:
        body = response.text
    return {"status_code": response.status_code, "body": body}


def fetch_seat():
    response = get(f"/events/{EVENT_ID}/seats/{SEAT_ID}")
    try:
        body = response.json()
    except Exception:
        body = response.text
    return {"status_code": response.status_code, "body": body}


def hold_race_test(concurrency=10):
    print("\n" + "=" * 80)
    print("TEST 1: HOLD RACE")
    print("=" * 80)

    users = [str(uuid.uuid4()) for _ in range(concurrency)]
    results = []

    with ThreadPoolExecutor(max_workers=concurrency) as executor:
        futures = [executor.submit(create_hold, user_id, 60) for user_id in users]
        for future in as_completed(futures):
            results.append(future.result())

    success = [r for r in results if r["status_code"] == 201]
    failed = [r for r in results if r["status_code"] != 201]

    print(f"Total requests: {len(results)}")
    print(f"Hold success count: {len(success)}")
    print(f"Hold failure count: {len(failed)}")

    for r in results:
        print(f"user={r['user_id']} status={r['status_code']} body={r['body']}")

    if len(success) == 1:
        print("✅ PASS: exactly one hold was created")
        hold_token = success[0]["body"]["hold_token"]
        winner = success[0]["user_id"]
        return hold_token, winner
    print("❌ FAIL: expected exactly one successful hold")
    return None, None


def booking_race_test(hold_token, winning_user, concurrency=5):
    print("\n" + "=" * 80)
    print("TEST 2: BOOKING RACE WITH SAME HOLD")
    print("=" * 80)

    results = []

    with ThreadPoolExecutor(max_workers=concurrency) as executor:
        futures = [
            executor.submit(
                create_booking,
                winning_user,
                hold_token,
                f"race-{i}-{uuid.uuid4()}",
            )
            for i in range(concurrency)
        ]
        for future in as_completed(futures):
            results.append(future.result())

    success = [r for r in results if r["status_code"] == 201]
    failed = [r for r in results if r["status_code"] != 201]

    print(f"Total booking requests: {len(results)}")
    print(f"Booking success count: {len(success)}")
    print(f"Booking failure count: {len(failed)}")

    for r in results:
        print(f"user={r['user_id']} status={r['status_code']} body={r['body']}")

    if len(success) == 1:
        print("✅ PASS: exactly one booking succeeded")
    else:
        print("❌ FAIL: expected exactly one successful booking")

    seat = fetch_seat()
    print(f"\nSeat after booking race: {seat['body']}")


def hold_expiry_test():
    print("\n" + "=" * 80)
    print("TEST 3: HOLD EXPIRY")
    print("=" * 80)

    user_id = str(uuid.uuid4())
    hold_result = create_hold(user_id, ttl_seconds=5)

    print(f"Hold create result: {hold_result}")
    if hold_result["status_code"] != 201:
        print("❌ FAIL: could not create hold for expiry test")
        return

    hold_token = hold_result["body"]["hold_token"]
    print("Waiting 6 seconds for hold to expire...")
    time.sleep(6)

    booking_result = create_booking(user_id, hold_token)
    print(f"Booking after expiry: {booking_result}")

    if booking_result["status_code"] in (409, 400):
        print("✅ PASS: expired hold correctly rejected")
    else:
        print("❌ FAIL: expired hold should not allow booking")


def release_and_rehold_test():
    print("\n" + "=" * 80)
    print("TEST 4: RELEASE AND RE-HOLD")
    print("=" * 80)

    first_user = str(uuid.uuid4())
    second_user = str(uuid.uuid4())

    first_hold = create_hold(first_user, ttl_seconds=60)
    print(f"First hold: {first_hold}")
    if first_hold["status_code"] != 201:
        print("❌ FAIL: first hold was not created")
        return

    hold_token = first_hold["body"]["hold_token"]
    release_result = release_hold(hold_token)
    print(f"Release result: {release_result}")

    second_hold = create_hold(second_user, ttl_seconds=60)
    print(f"Second hold: {second_hold}")

    if release_result["status_code"] == 200 and second_hold["status_code"] == 201:
        print("✅ PASS: seat became holdable again after release")
    else:
        print("❌ FAIL: release/re-hold flow is broken")


def main():
    if "PUT_EVENT_ID_HERE" in EVENT_ID or "PUT_SEAT_ID_HERE" in SEAT_ID:
        print("❌ Set EVENT_ID and SEAT_ID first")
        sys.exit(1)

    print(f"Using event_id={EVENT_ID}")
    print(f"Using seat_id={SEAT_ID}")

    seat = fetch_seat()
    print(f"Initial seat: {json.dumps(seat['body'], indent=2)}")

    hold_token, winning_user = hold_race_test()
    if hold_token and winning_user:
        booking_race_test(hold_token, winning_user)

    print("\n⚠️ For expiry/rehold tests, use a fresh available seat")
    print("If the seat is now booked, create another seat and rerun those tests.")


if __name__ == "__main__":
    main()
